// ---- Build Batches (PERSO-4422 Political Views) ----
const cfg = $('Config').first().json;
const L = cfg.lang;
const NEW_CUT = '2026-10-20 11:20';
const NL = String.fromCharCode(10);
const LING = ['qrcodelocalization@gmail.com','sabrathan@gmail.com','farahputri@gmail.com','dmluciahorea@gmail.com','roxanamoldovan25@gmail.com','mteres@terestraducciones.com','arandatrad@gmail.com','sara.guinot.trad@gmail.com','daniel@dgmultilingualservices.com','root-translations@outlook.com','austra.muizniece@gmail.com','harald.roald@gmail.com','47natcha@gmail.com','ellen.de.venter@outlook.com','ilaria.roncaglia@gmail.com','silke.luehrmann@gmx.de','boh.vozniuk@gmail.com','vidiasc@gmail.com','ivanaturcin@ymail.com','julius.valkiunas@gmail.com','jaromirvicari@me.com','karahansisman@gmail.com','katri.varvikko@gmail.com','kenneth@phraseit.dk','translation@cornell.hu','ruckova.lucia@gmail.com','marit.teichmann@gmail.com','michal.tosza@translators.org.pl','mteixeira@sacradomus.com','bruno@bsttranslations.com','nerissaneptuno@gmail.com','straus.translations@gmail.com','quentinnguyen.localize@gmail.com','therese.svardsten@gmail.com','mjlocalize@gmail.com','silis.martins@gmail.com'];
const LANGNAME = { es:'Spanish (Spain)', de:'German', fr:'French', it:'Italian', da:'Danish', nl:'Dutch', no:'Norwegian (Bokmål)', sv:'Swedish', pl:'Polish', pt:'Portuguese (Brazil)', ro:'Romanian', et:'Estonian', lv:'Latvian', lt:'Lithuanian', id:'Indonesian', ms:'Malay', ko:'Korean', th:'Thai' };
const STYLE = {
 es: ['Informal "tú" always, never usted.','Inclusive, neutral phrasing: "una persona…", "quienes…", "la ciudadanía"; avoid gendered adjectives about the user; never @, x or -e.','Sentence case in titles; always opening ¿ and ¡; exclamation marks sparingly.','Quotation marks «…» (as in the linguist edits).','"y" instead of "&"; "5 %" with a space.','Report = informe; test = test (plural invariable: los test).','Quadrant names: Left Authoritarian = Izquierda autoritaria, Left Libertarian = Izquierda libertaria, Right Authoritarian = Derecha autoritaria, Right Libertarian = Derecha libertaria (people: personas de la izquierda libertaria, etc.).','FAQ titles: "Q1:" becomes "P1:", "Q2:" "P2:" etc.','Lead-ins: "You may:" = "Es posible que:" + subjunctive items; "You tend to:" = "Tiendes a:" + infinitives; "You:" = "Tú:" + present-tense items; "You can:" = "Puedes:"; "You may benefit from:" = "Podrías beneficiarte de:"; "Ask yourself:" = "Pregúntate:"; "You may support:" = "Es posible que apoyes:".'],
 de: ['Address with "du" (lowercase du/dir/dich/dein); never "Sie" as address. Avoid a sentence starting with "Sie" meaning "they" (it reads as formal address): name the group instead.','Short sentences. Generic masculine, no gender star/colon.','Quotation marks „…“. "und" instead of "&". "10 %" with a space.','Report = Bericht; subscription = Mitgliedschaft (never Abonnement); E-Mail.','Personality rule: no personal verdicts like "du bist links-autoritär": say "Dein Ergebnis liegt im … Quadranten" and describe the group ("Menschen in diesem Quadranten …"). The test consists of statements users agree/disagree with: refer to their "Angaben", not "Antworten auf Fragen".','Quadrant names: Links-autoritär, Links-libertär, Rechts-autoritär, Rechts-libertär (people: Links-Libertäre, Rechts-Autoritäre …).','FAQ titles: "Q1:" becomes "F1:" etc.','Lead-ins: "You may:" = "Du könntest:" + infinitive items; "You tend to:" = "Du neigst dazu:" + zu-infinitives; "You:" = "Du:" + verb-first items (Erkennst …); "You can:" = "Du kannst:"; "You may benefit from:" = "Du könntest davon profitieren:"; "Ask yourself:" = "Frage dich:"; "You may support:" = "Vielleicht unterstützt du:".'],
 fr: ['Address the user with "vous".','Gender-neutral epicene phrasing; if impossible when addressing the user, add (e) in parentheses.','Mandatory non-breaking space (U+00A0) before : ; ? ! and inside « » quotes; French quotes « … ».','Much less capitalization than English (sentence case); accented capitals (À, É).','Straight apostrophe \'. "et" instead of "&". Fewer possessives (prefer articles).','Report = rapport. Headers in imperative if they are instructions; buttons in infinitive.'],
 it: ['Informal "tu".','Gender-neutral phrasing; if impossible use o/a (informato/a).','CTAs and buttons in imperative.','Accented capital È (never E\'). Quotes “…”. Straight apostrophe. "e" instead of "&". "5%" without space.','Keep copy brief, close to source length. Report = report/rapporto as in TM.'],
 da: ['Address with "du", never "De". Informal, helpful, natural; avoid word-for-word and noun-heavy language.','Gender-neutral words. Avoid over-use of possessive pronouns.','Sentence case. Straight quotes "…". "og" instead of "&". "5 %". Use en dash (tankestreg) where English uses a dash.','Exclamation marks and superlatives sparingly.'],
 nl: ['Informal "je/jij". Warm, welcoming, friendly self-care advice tone; paraphrasing allowed.','Gender-neutral; address with "je" rather than gendered nouns.','Sentence case. Straight quotes "…". No space before ? ! : ;. "en" instead of "&". "5%".','CTAs imperative, buttons infinitive.'],
 no: ['Bokmål. Address with "du". Informal, helpful, natural; avoid word-for-word and noun-heavy language.','Gender-neutral words. Avoid possessive pronouns where natural.','Sentence case. Quotes « ». "og" instead of "&". "5 %". En dash for ranges.','Exclamation marks and superlatives sparingly.'],
 sv: ['Address with "du". Informal, helpful, natural; avoid word-for-word and noun-heavy language.','Gender-neutral words. Avoid possessive pronouns where natural.','Sentence case. Typographic quotes ”…” (both ”). "och" instead of "&". "5 %". En dash for ranges.','Exclamation marks and superlatives sparingly.'],
 pl: ['Second person singular (ty), lowercase.','Gender-neutral forms: avoid gendered past-tense forms addressed to the user (use impersonal or present-tense constructions).','Avoid English-style passive voice. Friendly, natural, no literal structures.','Quotes „…”. En dash – instead of hyphen as a dash. "i" instead of "&". "99%" no space. Avoid exclamation marks.'],
 pt: ['Brazilian Portuguese. Address the user as "você" (mostly implicit) with 3rd-person verb forms.','Confident, helpful, formal but friendly tone (authoritative, science-based).','Gender-neutral wording; avoid articles in parentheses like (a).','Sentence case in headings; capitalize product names: Teste de Personalidade, Relatório de Personalidade, Área de Membros. Personality/Personality.co: masculine.','Curly quotes “…”. "e" instead of "&". "5%".'],
 ro: ['Informal "tu"; tone of curiosity and self-discovery; natural colloquial phrasing allowed.','Gender-neutral phrasing (e.g. "Sigur dorești…?" instead of "Ești sigur…?").','Sentence case. Quotes „…”. Comma-below ș and ț (never cedilla). "și" instead of "&". "5%".'],
 et: ['Address as "sina", never "teie". Informal but professional; no colloquialisms or slang.','Clear, not pronoun-heavy; rephrase freely; active voice.','Sentence case. Quotes „…“. En dash for ranges. "ja" instead of "&". "5%". Exclamation marks sparingly.'],
 lv: ['Formal address "jūs" (lowercase), but avoid overusing pronouns, especially possessives; user-friendly tone; creative, natural translation.','Never use variable gender endings like viņš(-a); avoid variable number endings.','Titles: noun phrase or imperative, no final period.','Sentence case. Quotes “…”. En dash, not em dash. "un" instead of "&". "5%".'],
 lt: ['Address as "jūs" (lowercase j); minimize pronouns ("Sukūrėme…" not "Mes sukūrėme…"). Semi-formal but friendly, short clear sentences; creative, natural.','Avoid gender-marked forms addressed to the user; use impersonal or plural constructions.','Sentence case. Quotes „…“. "ir" instead of "&". "5 %".'],
 id: ['Always "Anda" for you. Friendly tone, effective and concise, natural flow.','Gender-neutral.','Sentence case. Quotes “…”. "150%" no space.'],
 ms: ['Address as "anda" (lowercase). Friendly, inclusive, optimistic; not overly formal.','Gender-neutral pronouns.','Sentence case. Straight quotes "…". No space before ? ! : ;.'],
 ko: ['Avoid second-person pronouns; omit "you" where possible (use 귀하 only if really needed).','Friendly but polite endings: declarative sentences in the polite -요/-세요 style; questions with -니까?.','Sentences end with a period; no period in titles and headings. Straight quotes "…". Use 및 / 와(과) instead of "&". No space between number and unit; "5%".','Gender-neutral: no 그/그녀.'],
 th: ['Use คุณ for "you" (never ท่าน). No gendered particles (ครับ/ค่ะ). Semi-formal, approachable.','No full stop at sentence end; separate sentences with a space. Drop question marks (Thai particles mark questions). Exclamation marks may be dropped.','Always one space between Thai script and Latin script or digits. ๆ takes a space after it, not before. No non-breaking or zero-width spaces.','Straight quotes " ". Write และ instead of "&". Arabic numerals only.','Describe the quadrant as a group, not a verdict about the reader; the test items are ข้อความ (statements), not คำถาม; nothing reads as a diagnosis.']
};
const COMMON = [
 'You are a senior ' + LANGNAME[L] + ' translator localizing Personality.co, a personality-test website. This batch belongs to the new Political Views test: users rate 100 statements and get one of four results on a political compass (economic left/right x authoritarian/libertarian): Left Authoritarian, Left Libertarian, Right Authoritarian, Right Libertarian. The member-area report describes the user\'s quadrant; the funnel pages and welcome email sell the report.',
 'Translate English into ' + LANGNAME[L] + '. Return ONLY a JSON object mapping each key_id (string) to its translation. No preamble, no markdown.',
 '',
 'NEUTRALITY: political content. Stay strictly balanced and neutral: never make a quadrant sound better, worse, more extreme or more sympathetic than the English does. Use standard political-science terms of the target language. In this context "authoritarian" means preferring order and a strong state, not dictatorship; "libertarian" means maximum individual freedom (not the US party).',
 'PERSONALITY RULES: describe the quadrant or the group of people in it, never as a label or verdict on the reader (prefer "your result is in the X quadrant" over "you are an X"). When referring to the test itself, users agree or disagree with statements (FAQ titles stay questions). Nothing may read as a diagnosis or a replacement for therapy. Start from the positive framing as the English does.',
 'STYLE: natural, idiomatic, warm and clear. Translate meaning, not word by word. Same English term = same translation throughout. Headings and titles: sentence case of the target language, no final period. Keep the English sentence-final punctuation type (a sentence keeps its period, a heading has none) unless the language rules below say otherwise.',
 'LISTS: keys ending in ::start are lead-ins (often ending with ":"), and the following ::list::N keys are its items. Items must continue the lead-in grammatically and be parallel to each other.',
 'MARKUP: keep placeholders like [%1$s:name] exactly as written. Keep every tag (<span>…</span>, <email>…</email>, <link>…</link>, <nonLinkPeriod></nonLinkPeriod>) exactly, same count and order; translate only the text between tags. Keep personality.co / Personality.co and support@personality.co unchanged.',
 'REFERENCES: "tm" = an approved translation of the identical English in this project: reuse it verbatim unless it breaks a rule. "parallel" = how the same slot was translated in another quadrant\'s report ({en, t}): mirror its structure, lead-in wording and terminology. "Approved names" and "Linguist edits" show the house style: follow them. Glossary entries apply only when the English word is used in the same sense (many are UI terms such as Support or About).',
 '',
 LANGNAME[L] + ' RULES (style guide, mandatory):'
].join(NL) + NL + (STYLE[L] || []).map(function (s) { return '- ' + s; }).join(NL);

const all = [];
for (const it of $('Fetch Keys').all()) { for (const k of (((it.json || {}).body || {}).keys || [])) { all.push(k); } }
function nm(k) { return (typeof k.key_name === 'object') ? (k.key_name.web || k.key_name.other || '') : k.key_name; }
const Q = ['left_authoritarian','left_libertarian','right_authoritarian','right_libertarian'];
const QEN = { left_authoritarian:'Left Authoritarian', left_libertarian:'Left Libertarian', right_authoritarian:'Right Authoritarian', right_libertarian:'Right Libertarian' };
function rel(n) {
  for (const q of Q) {
    const a = 'components::members::profile::political_views_' + q + '::'; if (n.indexOf(a) === 0) { return { q: q, r: 'r:' + n.slice(a.length) }; }
    const b = 'components::members::profile::introduction::political_views_' + q + '::'; if (n.indexOf(b) === 0) { return { q: q, r: 'i:' + n.slice(b.length) }; }
  }
  return null;
}
const TM = {}; const lingEx = []; const refRel = {}; const names = {}; const todo = [];
let seen = 0, newN = 0, filledNew = 0, arch = 0;
for (const k of all) {
  seen++;
  if (k.is_archived) { arch++; continue; }
  const n = nm(k);
  let en = '', t = '', mb = '', ma = '';
  for (const tr of (k.translations || [])) { let v = tr.translation; if (v && typeof v === 'object') { v = JSON.stringify(v); } v = v || ''; if (tr.language_iso === 'en') { en = v; } if (tr.language_iso === L) { t = v; mb = tr.modified_by_email || ''; ma = tr.modified_at || ''; } }
  if (!en.trim()) { continue; }
  const isNew = String(k.created_at || '') >= NEW_CUT;
  if (!isNew) {
    if (t.trim() && !k.is_plural) { const e = en.trim(); const isL = LING.indexOf(mb) >= 0; if (!TM[e] || (isL && !TM[e].l)) { TM[e] = { t: t, l: isL }; } if (isL && en.length > 25 && en.length < 300) { lingEx.push({ en: en, t: t, m: ma }); } }
    continue;
  }
  newN++;
  const rq = rel(n);
  if (t.trim()) {
    filledNew++;
    if (rq && (!refRel[rq.r] || rq.q === 'left_authoritarian')) { refRel[rq.r] = { en: en, t: t, q: rq.q }; }
    if (/::name$/.test(n) && rq) { names[QEN[rq.q]] = t; }
    if (!TM[en.trim()]) { TM[en.trim()] = { t: t, l: false }; }
    continue;
  }
  if (k.is_plural) { continue; }
  todo.push({ id: k.key_id, n: n, en: en, d: String(k.description || '').slice(0, 200), rq: rq });
}
lingEx.sort(function (a, b) { return String(b.m).localeCompare(String(a.m)); });
const ling = lingEx.slice(0, 18);
// glossary
const gl = [];
for (const it of $('Fetch Glossary').all()) {
  for (const t of (((it.json || {}).body || {}).data || [])) {
    const tags = (t.tags || []).map(function (x) { return String(x).toLowerCase(); });
    if (tags.length && !tags.some(function (x) { return x === 'shared' || x.indexOf('personality') >= 0; })) { continue; }
    let tr = ''; for (const x of (t.translations || [])) { if (x.langIso === L && x.translation) { tr = x.translation; } }
    if (!t.term || t.term.length < 4) { continue; }
    if (t.translatable && !tr && !t.forbidden) { continue; }
    gl.push({ term: t.term, t: t.translatable ? tr : t.term, f: !!t.forbidden, d: String(t.description || '').slice(0, 80) });
  }
}
function esc(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function natural(a, b) { return a.localeCompare(b, 'en', { numeric: true }); }
// groups
const groups = {}; const order = [];
function add(g, x) { if (!groups[g]) { groups[g] = []; order.push(g); } groups[g].push(x); }
for (const x of todo) {
  if (/::name$/.test(x.n) || /trusts::political_views::\d$/.test(x.n) || /introduction::political_view$/.test(x.n) || /free_test_labels::political_views$/.test(x.n)) { add('0-names', x); continue; }
  if (x.rq) { add('1-' + x.rq.q, x); continue; }
  if (x.n.indexOf('email_templates::') === 0) { add('3-email', x); continue; }
  add('2-funnel', x);
}
const scope = cfg.scope;
let pick = order.filter(function (g) {
  if (scope === 'la') { return g === '0-names' || g === '1-left_authoritarian'; }
  if (scope === 'rest') { return g !== '1-left_authoritarian'; }
  return true;
}).sort();
const out = [];
for (const g of pick) {
  const ks = groups[g].sort(function (a, b) { return natural(a.n, b.n); });
  const chunks = [];
  if (g.indexOf('1-') === 0) {
    let cur = []; let curSec = '';
    for (const x of ks) {
      const sec = x.rq.r.split('::')[0];
      if (cur.length >= 45 && sec !== curSec) { chunks.push(cur); cur = []; }
      cur.push(x); curSec = sec;
    }
    if (cur.length) { chunks.push(cur); }
  } else { for (let i = 0; i < ks.length; i += 60) { chunks.push(ks.slice(i, i + 60)); } }
  chunks.forEach(function (c, ci) {
    const plain = c.map(function (x) { return x.en; }).join(NL).toLowerCase();
    const hits = gl.filter(function (e) { try { return new RegExp('\\b' + esc(e.term.toLowerCase()) + '\\b').test(plain); } catch (err) { return false; } }).slice(0, 40);
    const payload = c.map(function (x) {
      const o = { key_id: String(x.id), key: x.rq ? (QEN[x.rq.q] + ' report > ' + x.rq.r.slice(2)) : x.n.replace(/^components::|^pages::/, ''), en: x.en };
      if (x.d) { o.description = x.d; }
      const tm = TM[x.en.trim()]; if (tm) { o.tm = tm.t; }
      if (x.rq && refRel[x.rq.r] && !o.tm) { o.parallel = { en: refRel[x.rq.r].en, t: refRel[x.rq.r].t }; }
      return o;
    });
    const ctx = g === '0-names' ? 'Quadrant names and short labels (results page, member area). Choose clear, neutral political-compass names; they will be reused everywhere.' : g === '2-funnel' ? 'Landing page, results/paywall page, loader, payment-successful page and free-test labels of the Political Views test.' : g === '3-email' ? 'Welcome email sent after purchase.' : ('Member-area report for the ' + QEN[g.slice(2)] + ' quadrant, part ' + (ci + 1) + ' of ' + chunks.length + '.');
    const nameLines = Object.keys(names).map(function (e) { return '- ' + e + ' = ' + names[e]; }).join(NL) || '(none yet)';
    const user = 'Context: ' + ctx + NL + NL + 'Approved quadrant names in ' + LANGNAME[L] + ':' + NL + nameLines + NL + NL + 'Glossary (Lokalise; apply only in the same sense):' + NL + (hits.length ? hits.map(function (e) { return '- ' + e.term + (e.f ? ' (FORBIDDEN)' : ' = ' + e.t) + (e.d ? ' [' + e.d + ']' : ''); }).join(NL) : '(none)') + NL + NL + 'Linguist edits in this language (house style):' + NL + (ling.length ? ling.map(function (e) { return '- ' + e.en.replace(/\s+/g, ' ').slice(0, 160) + ' => ' + e.t.replace(/\s+/g, ' ').slice(0, 200); }).join(NL) : '(none)') + NL + NL + 'Keys (translate all ' + c.length + '; answer {"<key_id>": "<translation>"}):' + NL + JSON.stringify(payload);
    out.push({ json: { group: g + '#' + (ci + 1), lang: L, n: c.length, keys: c.map(function (x) { return { id: x.id, en: x.en }; }), system: COMMON, user: user } });
  });
}
const meta = { lang: L, scope: scope, keys_seen: seen, archived: arch, new_keys: newN, new_filled: filledNew, todo: todo.length, groups: out.length, tm: Object.keys(TM).length, ling_examples: ling.length, glossary_terms: gl.length, ref_slots: Object.keys(refRel).length, names: names };
const lim = cfg.max_groups || out.length;
const res = out.slice(0, lim);
for (const o of res) { o.json.meta = meta; }
if (!res.length) { return [{ json: { meta: meta, empty: true, group: 'none', n: 0, keys: [], system: '', user: '' } }]; }
return res;

function allRuns(name) { const out = []; for (let i = 0; i < 2000; i++) { let items; try { items = $(name).all(0, i); } catch (e) { break; } if (!items || !items.length) { break; } for (const it of items) { out.push(it.json); } } return out; }
const v = allRuns('Validate');
const w = allRuns('Write');
const meta = ($('Build Batches').first() || { json: {} }).json.meta || {};
const rows = v.map(function (x, i) { const r = w[i] || {}; return { group: x.group, keys: x.n, ok: x.ok, failed: x.failed, write_status: r.statusCode || null, write_errors: (r.body && r.body.errors && r.body.errors.length) ? JSON.stringify(r.body.errors).slice(0, 300) : null }; });
const preview = [];
for (const x of v) { for (const p of (x.preview || []).slice(0, $('Config').first().json.preview || 4)) { preview.push(Object.assign({ group: x.group }, p)); } }
return [{ json: { meta: meta, groups_done: rows.length, translated: rows.reduce(function (a, r) { return a + r.ok; }, 0), written: rows.reduce(function (a, r) { return a + (r.write_status === 200 ? r.ok : 0); }, 0), failed: rows.reduce(function (a, r) { return a.concat(r.failed); }, []), write_problems: rows.filter(function (r) { return r.write_status && r.write_status !== 200 || r.write_errors; }), groups: rows.map(function (r) { return r.group + ' ' + r.ok + '/' + r.keys + ' w' + r.write_status; }), preview: preview } }];

// ---- Validate & Build Payload (runOnceForEachItem) ----
const meta = $('Build Batches').first().json.meta || {};
if ((meta.keys_seen || 0) < 18000 || !(meta.glossary_terms > 0)) { throw new Error('Incomplete fetch (keys_seen ' + meta.keys_seen + ', glossary ' + meta.glossary_terms + '): rerun this language alone'); }
const b = $('Loop').item.json;
const r = $json || {};
let raw = ''; let apiErr = null;
if (r.choices && r.choices[0] && r.choices[0].message) { raw = String(r.choices[0].message.content || ''); } else { apiErr = 'OpenAI error: ' + JSON.stringify(r.error || r).slice(0, 200); }
let map = {}; let perr = apiErr;
if (!apiErr) { const s = raw.indexOf('{'), e = raw.lastIndexOf('}'); try { map = JSON.parse(raw.slice(s, e + 1)); } catch (err) { perr = String(err).slice(0, 200); } }
const PH = /\[%[^\]]*\]|%\d*\$?[sd]|\{\{[^}]+\}\}/g;
const TAG = /<\/?[A-Za-z][^>]*>/g;
const keys = []; const failed = []; const preview = [];
for (const k of (b.keys || [])) {
  let t = map[String(k.id)];
  if (typeof t !== 'string' || !t.trim()) { failed.push({ id: k.id, why: perr || 'missing' }); continue; }
  t = t.trim().replace(/\u200B/g, '');
  if (b.lang === 'th') { t = t.replace(/\u00A0/g, ' '); }
  if (b.lang === 'fr') { t = t.replace(/\u2019/g, "'"); }
  const p1 = (k.en.match(PH) || []).sort().join('|'), p2 = (t.match(PH) || []).sort().join('|');
  if (p1 !== p2) { failed.push({ id: k.id, why: 'placeholder mismatch', t: t.slice(0, 120) }); continue; }
  const t1 = (k.en.match(TAG) || []).join('|').toLowerCase(), t2 = (t.match(TAG) || []).join('|').toLowerCase();
  if (t1 !== t2) { failed.push({ id: k.id, why: 'tag mismatch', t: t.slice(0, 120) }); continue; }
  if (t === k.en.trim() && /[a-z]{4,}\s[a-z]{3,}/i.test(t)) { failed.push({ id: k.id, why: 'left in English', t: t.slice(0, 120) }); continue; }
  keys.push({ key_id: k.id, translations: [{ language_iso: b.lang, translation: t, is_unverified: true }] });
  preview.push({ id: k.id, en: k.en.slice(0, 140), t: t.slice(0, 200) });
}
return { json: { group: b.group, lang: b.lang, n: b.n, ok: keys.length, failed: failed, preview: preview, body: { keys: keys.length ? keys : [] }, usage: r.usage || null } };
